css:
.frame {
  width: 100%;
  max-width: 360px;
  margin: 16px;
  padding: 8px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  background: #fff;
}

.photo {
  display: block;
  width: 100%;
  max-width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover; /* crop, don't stretch */
  border-radius: 6px;
  background: #fed7aa;
}

.caption {
  margin: 8px 0 0;
  color: #52525b;
}
